#include "dispatch.h"

#include "../../include/solvapay.h"
#include "../../include/solvapay_fixture_host.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static const char *kClientOps[] = {
{{CLIENT_OPS}}
};

static const size_t kClientOpCount = sizeof(kClientOps) / sizeof(kClientOps[0]);

int contract_is_client_op(const char *fn) {
  if (fn == NULL) {
    return 0;
  }
  for (size_t i = 0; i < kClientOpCount; i++) {
    if (strcmp(fn, kClientOps[i]) == 0) {
      return 1;
    }
  }
  return 0;
}

static char *replay_client(size_t index, const char *fn, const char *args, char **fail_out) {
  char *base_url = NULL;
  int handle = solvapay_fh_stub_start(index, &base_url);
  int has_stub = handle > 0;
  if (!has_stub) {
    int no_wire = base_url != NULL && strstr(base_url, "has no wire") != NULL;
    if (!no_wire) {
      *fail_out = base_url;
      return NULL;
    }
    solvapay_free_string(base_url);
    base_url = NULL;
  }

  const char *origin = has_stub ? base_url : "http://127.0.0.1:1";
  char config[768];
  int n = snprintf(config, sizeof(config),
                   "{\"apiKey\":\"sk_test_fixture\",\"apiBaseUrl\":\"%s\"}",
                   origin ? origin : "");
  if (has_stub) {
    solvapay_free_string(base_url);
  }
  if (n < 0 || (size_t)n >= sizeof(config)) {
    if (has_stub) {
      *fail_out = solvapay_fh_stub_assert(handle);
    }
    return NULL;
  }

  SolvapayClient *client = NULL;
  SolvapayStatus status = solvapay_client_new(config, &client);
  if (status != SolvapayStatus_Ok || client == NULL) {
    if (has_stub) {
      *fail_out = solvapay_fh_stub_assert(handle);
    }
    return NULL;
  }

  char *env = solvapay_client_call(client, fn, args);
  solvapay_client_free(client);

  if (has_stub) {
    char *wire_diff = solvapay_fh_stub_assert(handle);
    if (wire_diff != NULL && wire_diff[0] != '\0') {
      solvapay_free_string(env);
      *fail_out = wire_diff;
      return NULL;
    }
    solvapay_free_string(wire_diff);
  }
  return env;
}

char *contract_replay(size_t index) {
  char *fn = solvapay_fh_fixture_fn(index);
  char *args = solvapay_fh_fixture_args(index);
  if (fn == NULL || args == NULL) {
    solvapay_free_string(fn);
    solvapay_free_string(args);
    return NULL;
  }

  char *fail = NULL;
  char *env = NULL;
  if (contract_is_client_op(fn)) {
    env = replay_client(index, fn, args, &fail);
    if (env == NULL) {
      solvapay_free_string(fn);
      solvapay_free_string(args);
      return fail;
    }
  } else if (strcmp(fn, "verifyWebhook") == 0) {
    env = solvapay_verify_webhook(args);
  } else {
    env = solvapay_fh_call_sync(fn, args);
  }

  solvapay_free_string(fn);
  solvapay_free_string(args);
  return env;
}

