#ifndef SOLVAPAY_CONTRACT_DISPATCH_H
#define SOLVAPAY_CONTRACT_DISPATCH_H

#include <stddef.h>

/* Returns 1 when `fn` is a catalogued client operation. */
int contract_is_client_op(const char *fn);

/*
 * Replays fixture `index` through the C boundary (client/webhook) or the
 * fixture-host sync registry. Caller frees the returned envelope with
 * solvapay_free_string.
 */
char *contract_replay(size_t index);

#endif

