#include "harness.h"
#include "dispatch.h"

#include "../../include/solvapay.h"
#include "../../include/solvapay_fixture_host.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int contract_run_census(size_t want_parsed, size_t want_replayed) {
  size_t parsed = solvapay_fh_fixture_count();
  if (parsed != want_parsed) {
    fprintf(stderr, "FAIL: parsed=%zu want=%zu\n", parsed, want_parsed);
    return 1;
  }

  size_t replayed = 0;
  size_t issues = 0;
  for (size_t i = 0; i < parsed; i++) {
    char *label = solvapay_fh_fixture_label(i);
    char *env = contract_replay(i);
    if (env == NULL) {
      fprintf(stderr, "FAIL %s: replay returned null\n", label ? label : "?");
      solvapay_free_string(label);
      issues++;
      continue;
    }
    char *diff = solvapay_fh_assert(i, env);
    if (diff != NULL && diff[0] != '\0') {
      fprintf(stderr, "FAIL %s: %s\nenvelope=%s\n", label ? label : "?", diff, env);
      issues++;
    } else {
      replayed++;
    }
    solvapay_free_string(diff);
    solvapay_free_string(env);
    solvapay_free_string(label);
  }

  if (replayed != want_replayed || issues > 0) {
    fprintf(stderr,
            "FAIL: fixture census parsed=%zu replayed=%zu wantReplayed=%zu issues=%zu\n",
            parsed, replayed, want_replayed, issues);
    return 1;
  }

  printf("OK: C fixture conformance parsed=%zu replayed=%zu\n", parsed, replayed);
  return 0;
}

